$node=(Get-Command node.exe).Source
$npm=Join-Path (Split-Path -Parent $node) 'node_modules/npm/bin/npm-cli.js'
python .github/scripts/stage_runtime_bundle_023.py --platform win32-x64 --build-node $node --npm-cli $npm --output test/out/ownership-runtime-stage
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$name=if('${{ inputs.admission_run }}' -in @('ordinary-startup-023','ordinary-startup-initialized-023','ordinary-lifecycle-023')){'OCXD_STARTUP_PROBE_RUNTIME'}else{'OCXD_OWNERSHIP_PROBE_RUNTIME'}
$name+'='+[IO.Path]::GetFullPath('test/out/ownership-runtime-stage/platform-bundle/runtime-bundle') >> $env:GITHUB_ENV
if('${{ inputs.admission_run }}' -in @('ordinary-startup-initialized-023','ordinary-lifecycle-023')){'OCXD_STARTUP_PROBE_INITIALIZE_CODEX=1' >> $env:GITHUB_ENV}
if('${{ inputs.admission_run }}' -ceq 'ordinary-lifecycle-023'){'OCXD_STARTUP_PROBE_LIFECYCLE=1' >> $env:GITHUB_ENV}
if('${{ inputs.admission_run }}' -ceq 'ordinary-stop-readonly-023'){'OCXD_READONLY_STOP_COSTS=${{ matrix.stop_order }}' >> $env:GITHUB_ENV}
if('${{ inputs.admission_run }}' -ceq 'ordinary-native-wrapper-023'){'OCXD_READONLY_STOP_COSTS=native-only' >> $env:GITHUB_ENV}
New-Item -ItemType Directory -Force test/out/windows023-ordinary-preflight | Out-Null
python test/smoke/verify-pinned-profile-source.py test/out/ownership-runtime-stage/platform-bundle/runtime-bundle/runtime/opencodex/node_modules/@bitkyc08/opencodex test/out/windows023-ordinary-preflight/stop-source-attestation.json --ordinary-stop-profile
if($LASTEXITCODE -ne 0){throw 'Pinned original stop sources differ'}
$taskStatic = Join-Path $env:RUNNER_TEMP ('ocxd023-preflight-static-' + [guid]::NewGuid().ToString('N'))
& test/smoke/windows023-rust-ordinary.test.ps1 -OutputDirectory $taskStatic
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$taskEvidence = Join-Path $env:RUNNER_TEMP ('ocxd023-preflight-native-' + [guid]::NewGuid().ToString('N'))
try {
  & test/smoke/windows023-rust-ordinary.ps1 -Cargo (Get-Command cargo.exe).Source -ManifestPath (Join-Path $PWD 'test/smoke/windows023-ordinary-preflight/Cargo.toml') -Node (Get-Command node.exe).Source -OutputDirectory $taskEvidence -ExpectedCommit (git rev-parse HEAD)
  if ($LASTEXITCODE -ne 0) { throw 'Ordinary runner preflight failed; original receipts retained' }
} finally {
  New-Item -ItemType Directory -Force test/out/windows023-ordinary-preflight | Out-Null
  if (Test-Path -LiteralPath $taskEvidence) { Copy-Item -LiteralPath $taskEvidence -Destination test/out/windows023-ordinary-preflight/native -Recurse }
}
